WITH with_windows AS (SELECT *, ROUND(rating / SUM(rating) OVER (PARTITION BY country), 4) AS rating_share, CUME_DIST() OVER (PARTITION BY country ORDER BY rating NULLS FIRST) AS rating_cume_dist, COUNT(rating) OVER (PARTITION BY country, city) AS country_count_rating FROM suppliers WHERE city IN ('Chiang Mai', 'Tokyo')) SELECT id, supplier_name, city, country_count_rating FROM with_windows ORDER BY country_count_rating DESC
